 DECLARE @Targets TABLE(id uniqueidentifier PRIMARY KEY,reconciliation_id uniqueidentifier,old_version int,new_version int,old_updated_at datetimeoffset(7),new_updated_at datetimeoffset(7),cloud_audit_id uniqueidentifier,expected_after_signature varchar(64));
 INSERT @Targets SELECT * FROM OPENJSON(@TargetJson) WITH(id uniqueidentifier,reconciliation_id uniqueidentifier,old_version int,new_version int,old_updated_at datetimeoffset(7),new_updated_at datetimeoffset(7),cloud_audit_id uniqueidentifier,expected_after_signature varchar(64));
 IF (SELECT COUNT(*) FROM @Targets)<>3 OR EXISTS(SELECT 1 FROM @Targets WHERE old_version<>5 OR new_version<>6 OR id='f7c9512a-92dc-4f88-b49d-71d55c577670') THROW 51154,'LOCAL54 invalid exact three-shift scope.',1;
 BEGIN TRANSACTION;
 -- Receipt, parent and complete child locks. Busy records abort, never retry.
 IF (SELECT COUNT(*) FROM dbo.local_operation_receipts WITH(UPDLOCK,HOLDLOCK,NOWAIT) WHERE operation_id=@Repair)>1 THROW 51154,'LOCAL54 ambiguous receipt identity.',1;
 DECLARE @ReceiptNote nvarchar(400),@ReceiptExists bit=0;SELECT @ReceiptExists=1,@ReceiptNote=note FROM dbo.local_operation_receipts WITH(UPDLOCK,HOLDLOCK,NOWAIT) WHERE operation_id=@Repair;
 IF @ReceiptExists=1 AND @ReceiptNote IS NULL THROW 51154,'LOCAL54 incomplete existing receipt.',1;
 DECLARE @Lock uniqueidentifier;SELECT @Lock=s.id FROM dbo.shifts s WITH(UPDLOCK,HOLDLOCK,NOWAIT) JOIN @Targets t ON t.id=s.id ORDER BY CONVERT(nvarchar(36),s.id);
 IF (SELECT COUNT(*) FROM dbo.shifts s JOIN @Targets t ON t.id=s.id WHERE s.store_id=@Branch AND s.status=N'CLOSED' AND s.state=N'CLOSED' AND s.closed_at IS NOT NULL)<>3 THROW 51154,'LOCAL54 parent identity/status changed.',1;
 DECLARE @Before TABLE(table_name nvarchar(128),id uniqueidentifier,signature varchar(64));
 INSERT @Before SELECT N'shifts' table_name,source.id,CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),CONVERT(nvarchar(max),N'shifts|')+canonical.facts)),2) signature
 FROM dbo.[shifts] source WITH(UPDLOCK,HOLDLOCK,NOWAIT) LEFT JOIN @Targets t ON t.id=source.id
