 SELECT @BeforeDigest=CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),STRING_AGG(CONVERT(nvarchar(max),table_name+N':'+LOWER(CONVERT(nvarchar(36),id))+N':'+signature),NCHAR(30)) WITHIN GROUP(ORDER BY table_name,CONVERT(nvarchar(36),id)))),2) FROM @ExpectedBefore;
 SELECT @AfterDigest=CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),STRING_AGG(CONVERT(nvarchar(max),table_name+N':'+LOWER(CONVERT(nvarchar(36),id))+N':'+signature),NCHAR(30)) WITHIN GROUP(ORDER BY table_name,CONVERT(nvarchar(36),id)))),2) FROM @Proposed;
 IF @ReceiptNote IS NOT NULL BEGIN
  IF ISJSON(@ReceiptNote)<>1 OR ISNULL(JSON_VALUE(@ReceiptNote,'$.k'),N'')<>N'LOCAL54' OR ISNULL(JSON_VALUE(@ReceiptNote,'$.b'),N'')<>@BeforeDigest OR ISNULL(JSON_VALUE(@ReceiptNote,'$.a'),N'')<>@AfterDigest OR ISNULL(JSON_VALUE(@ReceiptNote,'$.s'),N'')<>N'EDE776AB307BA37E77908ECCE27F950BD68EF410A35A9DDF167B32833DCF56C6' OR ISNULL(JSON_VALUE(@ReceiptNote,'$.u'),N'')<>SUSER_SNAME() OR NOT EXISTS(SELECT 1 FROM dbo.local_operation_receipts WHERE operation_id=@Repair AND operation_type=N'cloud_shift_summary_mirror' AND entity_id=@Branch AND CONVERT(nvarchar(40),committed_at,127)=JSON_VALUE(@ReceiptNote,'$.t')) OR EXISTS(SELECT * FROM @Before EXCEPT SELECT * FROM @Proposed) OR EXISTS(SELECT * FROM @Proposed EXCEPT SELECT * FROM @Before) THROW 51154,'LOCAL54 replay receipt/current facts mismatch.',1;
  IF EXISTS(SELECT 1 FROM OPENJSON(@Columns) WITH(table_name sysname,column_name sysname,[type] nvarchar(100),expected_nullable bit '$.nullable') e LEFT JOIN sys.columns c ON c.object_id=OBJECT_ID(N'dbo.'+QUOTENAME(e.table_name)) AND c.name=e.column_name WHERE c.column_id IS NULL OR c.is_computed<>0 OR c.is_nullable<>e.expected_nullable OR LOWER(TYPE_NAME(c.user_type_id))+CASE WHEN TYPE_NAME(c.user_type_id) IN('nvarchar','nchar') THEN N'('+CASE WHEN c.max_length=-1 THEN N'max' ELSE CONVERT(nvarchar(10),c.max_length/2) END+N')' WHEN TYPE_NAME(c.user_type_id) IN('decimal','numeric') THEN N'('+CONVERT(nvarchar(10),c.precision)+N','+CONVERT(nvarchar(10),c.scale)+N')' WHEN TYPE_NAME(c.user_type_id) IN('datetimeoffset','datetime2','time') THEN N'('+CONVERT(nvarchar(10),c.scale)+N')' ELSE N'' END<>e.[type]) THROW 51154,'LOCAL54 registered schema changed.',1;
 IF EXISTS(SELECT e.table_name FROM OPENJSON(@Columns) WITH(table_name sysname) e GROUP BY e.table_name HAVING COUNT(*)<>(SELECT COUNT(*) FROM sys.columns c WHERE c.object_id=OBJECT_ID(N'dbo.'+QUOTENAME(e.table_name)))) THROW 51154,'LOCAL54 registered column set changed.',1;
 IF (SELECT COUNT(*) FROM sys.triggers WHERE parent_id IN(OBJECT_ID(N'dbo.shifts'),OBJECT_ID(N'dbo.shift_cash_counts'),OBJECT_ID(N'dbo.shift_reconciliations'),OBJECT_ID(N'dbo.shift_close_events'),OBJECT_ID(N'dbo.shift_notifications'),OBJECT_ID(N'dbo.shift_variance_alerts'),OBJECT_ID(N'dbo.local_operation_receipts')) AND is_disabled=0)<>1 OR NOT EXISTS(SELECT 1 FROM sys.triggers WHERE parent_id=OBJECT_ID(N'dbo.shifts') AND name=N'shifts_unfinished_tickets' AND is_disabled=0 AND CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(object_id))),2)='3BB304E7D93DD5F747133EF3FE5CF558C61D4CFBF4A5603B3001295F365C4949') THROW 51154,'LOCAL54 trigger definition changed.',1;
