 DECLARE @Committed datetimeoffset(7)=SYSDATETIMEOFFSET();
 DECLARE @Note nvarchar(max)=(SELECT N'LOCAL54' k,@BeforeDigest b,@AfterDigest a,N'EDE776AB307BA37E77908ECCE27F950BD68EF410A35A9DDF167B32833DCF56C6' s,SUSER_SNAME() u,CONVERT(nvarchar(40),@Committed,127) t FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
 IF DATALENGTH(@Note)>800 THROW 51154,'LOCAL54 honest maintenance receipt exceeds capacity.',1;
 INSERT dbo.local_operation_receipts(operation_id,operation_type,entity_id,note,committed_at) VALUES(@Repair,N'cloud_shift_summary_mirror',@Branch,@Note,@Committed);
 IF @@ROWCOUNT<>1 OR NOT EXISTS(SELECT 1 FROM dbo.local_operation_receipts WHERE operation_id=@Repair AND note=@Note) THROW 51154,'LOCAL54 receipt was not acknowledged.',1;
 IF EXISTS(SELECT 1 FROM OPENJSON(@Columns) WITH(table_name sysname,column_name sysname,[type] nvarchar(100),expected_nullable bit '$.nullable') e LEFT JOIN sys.columns c ON c.object_id=OBJECT_ID(N'dbo.'+QUOTENAME(e.table_name)) AND c.name=e.column_name WHERE c.column_id IS NULL OR c.is_computed<>0 OR c.is_nullable<>e.expected_nullable OR LOWER(TYPE_NAME(c.user_type_id))+CASE WHEN TYPE_NAME(c.user_type_id) IN('nvarchar','nchar') THEN N'('+CASE WHEN c.max_length=-1 THEN N'max' ELSE CONVERT(nvarchar(10),c.max_length/2) END+N')' WHEN TYPE_NAME(c.user_type_id) IN('decimal','numeric') THEN N'('+CONVERT(nvarchar(10),c.precision)+N','+CONVERT(nvarchar(10),c.scale)+N')' WHEN TYPE_NAME(c.user_type_id) IN('datetimeoffset','datetime2','time') THEN N'('+CONVERT(nvarchar(10),c.scale)+N')' ELSE N'' END<>e.[type]) THROW 51154,'LOCAL54 registered schema changed.',1;
 IF EXISTS(SELECT e.table_name FROM OPENJSON(@Columns) WITH(table_name sysname) e GROUP BY e.table_name HAVING COUNT(*)<>(SELECT COUNT(*) FROM sys.columns c WHERE c.object_id=OBJECT_ID(N'dbo.'+QUOTENAME(e.table_name)))) THROW 51154,'LOCAL54 registered column set changed.',1;
 IF (SELECT COUNT(*) FROM sys.triggers WHERE parent_id IN(OBJECT_ID(N'dbo.shifts'),OBJECT_ID(N'dbo.shift_cash_counts'),OBJECT_ID(N'dbo.shift_reconciliations'),OBJECT_ID(N'dbo.shift_close_events'),OBJECT_ID(N'dbo.shift_notifications'),OBJECT_ID(N'dbo.shift_variance_alerts'),OBJECT_ID(N'dbo.local_operation_receipts')) AND is_disabled=0)<>1 OR NOT EXISTS(SELECT 1 FROM sys.triggers WHERE parent_id=OBJECT_ID(N'dbo.shifts') AND name=N'shifts_unfinished_tickets' AND is_disabled=0 AND CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(object_id))),2)='3BB304E7D93DD5F747133EF3FE5CF558C61D4CFBF4A5603B3001295F365C4949') THROW 51154,'LOCAL54 trigger definition changed.',1;
 IF COL_LENGTH(N'dbo.local_operation_receipts',N'operation_id')<>16 OR COL_LENGTH(N'dbo.local_operation_receipts',N'operation_type')<>80 OR COL_LENGTH(N'dbo.local_operation_receipts',N'entity_id')<>256 OR COL_LENGTH(N'dbo.local_operation_receipts',N'note')<>800 OR NOT EXISTS(SELECT 1 FROM sys.columns WHERE object_id=OBJECT_ID(N'dbo.local_operation_receipts') AND name=N'committed_at' AND TYPE_NAME(user_type_id)=N'datetimeoffset' AND scale=7) THROW 51154,'LOCAL54 receipt schema changed.',1;
 IF NOT EXISTS(SELECT 1 FROM sys.indexes i JOIN sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id JOIN sys.columns c ON c.object_id=ic.object_id AND c.column_id=ic.column_id WHERE i.object_id=OBJECT_ID(N'dbo.local_operation_receipts') AND i.is_unique=1 AND i.is_disabled=0 AND i.has_filter=0 AND c.name=N'operation_id' AND c.is_nullable=0 AND ic.key_ordinal=1 AND (SELECT COUNT(*) FROM sys.index_columns extra WHERE extra.object_id=i.object_id AND extra.index_id=i.index_id AND extra.key_ordinal>0)=1) THROW 51154,'LOCAL54 receipt identity constraint changed.',1;
 IF EXISTS(SELECT 1 FROM (VALUES (N'shifts'),(N'shift_cash_counts'),(N'shift_reconciliations'),(N'shift_close_events'),(N'shift_notifications'),(N'shift_variance_alerts')) names(name) WHERE NOT EXISTS(SELECT 1 FROM sys.indexes i JOIN sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id JOIN sys.columns c ON c.object_id=ic.object_id AND c.column_id=ic.column_id WHERE i.object_id=OBJECT_ID(N'dbo.'+QUOTENAME(names.name)) AND i.is_primary_key=1 AND i.is_disabled=0 AND c.name=N'id' AND ic.key_ordinal=1 AND (SELECT COUNT(*) FROM sys.index_columns extra WHERE extra.object_id=i.object_id AND extra.index_id=i.index_id AND extra.key_ordinal>0)=1)) THROW 51154,'LOCAL54 registered row identity constraint changed.',1;
 IF (SELECT COUNT(*) FROM sys.change_tracking_tables WHERE object_id IN(OBJECT_ID(N'dbo.shifts'),OBJECT_ID(N'dbo.shift_cash_counts'),OBJECT_ID(N'dbo.shift_reconciliations'),OBJECT_ID(N'dbo.shift_close_events'),OBJECT_ID(N'dbo.shift_notifications'),OBJECT_ID(N'dbo.shift_variance_alerts')))<>6 THROW 51154,'LOCAL54 registered Change Tracking changed.',1;
 COMMIT;IF @HadXactAbort=0 SET XACT_ABORT OFF;
 SELECT N'MIRRORED THREE / not full branch recovery' result,@Repair operation_id;
END TRY
BEGIN CATCH
 IF XACT_STATE()<>0 ROLLBACK;
 IF @HadXactAbort=0 SET XACT_ABORT OFF;
 THROW;
END CATCH;
